"use client";
/**
 * HR & Payroll (source L23824–L24462, v62 + v63): data model, demo data, roles, audit, CSV / XLSX import and export,
 * the application shell (navigation, breadcrumb, pages, drawer, dialogs) and every page.
 *
 * Deliberate structure (ADR-04 exception, as for the registration wizard and Remotion AI): the source builds the app
 * from string templates written with innerHTML and patched in place. It is ported as a typed imperative island that
 * fills the `.hr` container the window body mounts once. The code below is the source's own text (templates are
 * byte-identical) with types added; only the OS integration at the end is replaced by the React window wiring
 * (src/apps/hr/HrApp.tsx). Its shared pieces (escaping, icons, dialogs, toasts, dates, money) are the kit the
 * healthcare apps reuse (B-17).
 *
 * Simulated as in the source (S class): roles and permissions are a browser-side demo; all people, organisations,
 * contracts and amounts are fictitious; payroll is not computed.
 */
import { L4 as L4core } from "@/lib/i18n/core";
import { isLang, type Lang } from "@/lib/i18n/langs";
import { lkRM } from "@/os/lock/lock";
import { useShell } from "@/os/state/shell";
import { osMenu, type MenuItem } from "@/os/menu/OsMenu";
import { unzip } from "@/lib/zip";
import { dcSaveFile } from "@/lib/download";
import registry from "@/apps/registry.data.json";
import { secCsv } from "@/lib/security";
import { orgToday } from "@/lib/storage/orgday";

/* ---------- typed model ---------- */
export type HrHist = { d: string; t: string };
export type HrLeave = { id: string; type: string; from: string; to: string; st: string; days: number; by?: string; at?: string; why?: string; note?: string };
export type HrDocRec = { id: string; type: string; d: string; name: string; size: number; file: string | null; mime?: string };
export type HrContract = { type: string; start: string; end: string; trialEnd: string; cc: string; hist?: HrHist[] };
export type HrPay = { gross: number; period: string; cur: string; note?: string };
export type HrEmp = {
  id: string; mat: string; first: string; last: string; title: string; job: string; dept: string; est: string; team: string; mgr: string | null;
  email: string; phone: string; entry: string; contract: HrContract; status: string; wt: number; hours: number; schedule: string; pay: HrPay;
  birth: string; addr: string; emergency: string; leaves: HrLeave[]; docs: HrDocRec[]; hist: HrHist[]; synthetic?: boolean; archived?: boolean;
  leftOn?: string; suspension?: { from: string; to: string; reason: string }; created?: string;
};
export type HrAudit = { id: string; ts: string; role: string; user: string; act: string; ref: string; detail: string };
export type HrSet = { endAlert: number; cards: boolean; saved: { id?: string; n: string; f: HrFlt }[]; hide?: string[]; dense?: boolean; group?: string };
export type HrState = { v: number; seeded: string; synthetic: boolean; role: string; meMgr: string; set: HrSet; org: string; ests: { id: string; n: string }[]; depts: { id: string; n: string }[]; emps: HrEmp[]; audit: HrAudit[] };
export type HrFlt = { q?: string; status?: string[]; ctype?: string[]; csit?: string[]; dept?: string; est?: string; job?: string; mgr?: string; from?: string; to?: string; wt?: string; avail?: string; showLeft?: boolean; showArch?: boolean };
type Dict = Record<string, string>;
/** A loosely typed object read from a source template / JSON (import rows, patches): property bags only. */
type Bag = Record<string, unknown>;

const lang = (): Lang => { const h = document.documentElement.lang; return isLang(h) ? h : "en"; };
/** L4 (L21374): "fr|en|de|ar" → the current language. */
const L4 = (s: string) => L4core(lang(), s);
const toast = (m: string) => useShell.getState().showToast(m);
const DK_APPS = registry.DK_APPS as unknown as Record<string, [string, string]>;
const OS_USER: { name?: string } | null = null;
/** OSW.hrPeople.el (the window) — found by its key. */
const hrWinEl = () => document.querySelector<HTMLElement>('.os-win[data-osw="hrPeople"]');
type HTMLElementX = HTMLElement & { _close?: () => void; _t?: ReturnType<typeof setTimeout>; _sync?: () => void };
const tgt = (e: Event) => e.target as HTMLInputElement;
type HrPageDef = { id: string; g: string; n: string; ic: string; page: (a: string | null) => string; mount?: (R: HTMLElement) => void; hidden?: boolean; soon?: boolean; perm?: string | string[]; badge?: () => number;
  click?: (e: MouseEvent, c: (s: string) => HTMLInputElement | null) => void; input?: (e: Event) => void; change?: (e: Event) => void };
type DlgOpts = { wide?: boolean; xl?: boolean; icon?: string; foot?: string; cancel?: boolean; cancelLabel?: string; ok?: boolean; okLabel?: string; danger?: boolean; onOk?: (m: HTMLElementX) => boolean | void; mount?: (m: HTMLElementX) => void };
type HrWizFile = { name: string; size: number; type: string; file: string | null; mime?: string };
type HrMenuItem = MenuItem;
type HrWiz = ReturnType<typeof hrWizBlank>;
/**
 * The source's module-level listeners (click / input / change / keydown on the document, storage on the window). They are
 * registered the first time the HR window mounts (hrInstallGlobal), not when this module loads: the source adds them
 * after the OS menu's outside-click listener (L11708), and that order matters — the menu closes the previous menu first,
 * then HR opens its own. The handlers only act inside the HR window, so registering them later changes nothing else.
 */
const pendingGlobal: (() => void)[] = [];
const onDoc = <K extends keyof DocumentEventMap>(ev: K, fn: (e: DocumentEventMap[K]) => void, cap?: boolean) => { pendingGlobal.push(() => document.addEventListener(ev, fn, cap)); };
const onWin = <K extends keyof WindowEventMap>(ev: K, fn: (e: WindowEventMap[K]) => void) => { pendingGlobal.push(() => window.addEventListener(ev, fn)); };
let globalDone = false;
export function hrInstallGlobal() { if (globalDone) return; globalDone = true; pendingGlobal.forEach((f) => f()); }

