const HR_SORTS=[["name","Nom|Name|Name|الاسم"],["entry","Date d’entrée|Start date|Eintritt|الالتحاق"],["job","Poste|Job title|Position|الوظيفة"],["status","Statut|Status|Status|الحالة"]];
