function hrFltCount(f: HrFlt){return HR_FKEYS.filter(k=>Array.isArray((f as Bag)[k])?((f as Bag)[k] as string[]).length:(f as Bag)[k]).length}
function hrQuery(f: HrFlt,o: { nogroup?: boolean }={}){const q=String(f.q||"").trim().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");const norm=(s: unknown)=>String(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");const has=(k: "status" | "ctype" | "csit",v: string)=>!f[k]||!f[k].length||f[k].includes(v);
  let rows=HR.st!.emps.filter(e=>hrVisible(e)&&(f.showLeft||e.status!=="left"||(f.status||[]).includes("left"))&&(!e.archived||f.showArch));
  rows=rows.filter(e=>(!q||norm(hrName(e)+" "+e.last+" "+e.first+" "+e.mat+" "+e.email+" "+e.job+" "+hrEstName(e.est)+" "+(e.team||"")+" "+hrDeptName(e.dept)).includes(q))&&has("status",e.status)&&has("ctype",e.contract.type)&&(!f.dept||e.dept===f.dept)&&(!f.est||e.est===f.est)&&(!f.job||e.job===f.job)&&(!f.mgr||e.mgr===f.mgr)&&(!f.from||e.entry>=f.from)&&(!f.to||e.entry<=f.to)&&(!f.wt||(f.wt==="full"?e.wt>=100:e.wt<100))&&has("csit",hrCSit(e))&&(!f.avail||hrAvail(e)===f.avail));
  const k=HR.ui.sort,d=HR.ui.dir;const val=(e: HrEmp)=>k==="name"?norm(e.last+" "+e.first):k==="entry"?e.entry:k==="job"?norm(e.job):k==="status"?["active","trial","suspended","left"].indexOf(e.status):k==="dept"?norm(hrDeptName(e.dept)):k==="est"?norm(hrEstName(e.est)):k==="mgr"?norm(hrMgrName(e.mgr)):k==="ctype"?e.contract.type:k==="wt"?e.wt:k==="mat"?e.mat:norm(e.last);
  rows.sort((a,b)=>{const x=val(a),y=val(b);return (x>y?1:x<y?-1:0)*d||(a.mat>b.mat?1:-1)});if(HR.ui.group&&!o.nogroup){const gs=(e: HrEmp)=>hrGroupLabel(hrGroupKey(e));rows.sort((a,b)=>gs(a).localeCompare(gs(b),hrLoc()))}return rows}
