function hrKpis(){const v=HR.st!.emps.filter(e=>hrVisible(e)&&!e.archived);const cur=v.filter(e=>e.status!=="left");return {total:cur.length,active:cur.filter(e=>e.status==="active").length,trial:cur.filter(e=>e.status==="trial").length,ending:cur.filter(e=>hrCSit(e)==="ending").length,leave:cur.filter(e=>hrAvail(e)==="leave").length,left:v.filter(e=>e.status==="left").length}}
