const HR_ACTS: Dict ={"emp.create":"Dossier créé|Record created|Akte angelegt|إنشاء ملف","emp.update":"Dossier modifié|Record updated|Akte geändert|تعديل ملف","emp.deactivate":"Sortie des effectifs|Left the organisation|Ausgeschieden|مغادرة","emp.archive":"Dossier archivé|Record archived|Akte archiviert|أرشفة","emp.reveal":"Données personnelles consultées|Personal data viewed|Persönliche Daten angesehen|عرض البيانات الشخصية","doc.add":"Document ajouté|Document added|Dokument hinzugefügt|إضافة مستند","doc.del":"Document supprimé|Document removed|Dokument entfernt|حذف مستند","contract.amend":"Avenant au contrat|Contract amended|Vertragsnachtrag|تعديل العقد","leave.approved":"Congé approuvé|Leave approved|Urlaub genehmigt|موافقة على إجازة","leave.refused":"Congé refusé|Leave refused|Urlaub abgelehnt|رفض إجازة","leave.request":"Demande de congé|Leave requested|Urlaubsantrag|طلب إجازة","export":"Export|Export|Export|تصدير","import":"Import|Import|Import|استيراد","role.switch":"Changement de rôle (démo)|Role switched (demo)|Rolle gewechselt|تغيير الدور","bulk":"Action groupée|Bulk action|Sammelaktion|إجراء جماعي","seed":"Données de démonstration|Demo data|Demodaten|بيانات تجريبية","settings":"Paramètres modifiés|Settings changed|Einstellungen geändert|تغيير الإعدادات"};
