function hrContractHTML(e: HrEmp){const c=e.contract;const cd=(e.docs||[]).filter(d=>d.type==="contract"||d.type==="amend");return `<div class="hr-pgrid"><section class="hr-card hr-contract"><h3>${hri("sign",16)}${hrE(L4("Contrat en cours|Current contract|Aktueller Vertrag|العقد الحالي"))}</h3><div class="hr-cbig"><span class="hr-ct ${c.type} lg">${hrE(L4(HR_CTYPES[c.type]))}</span>${hrCsBadge(hrCSit(e))||`<span class="hr-cs running">${hrE(L4(HR_CSIT.running))}</span>`}</div>
   ${c.end?`<div class="hr-span"><span>${hrE(hrDate(c.start||e.entry))}</span><i style="--p:${Math.max(0,Math.min(100,hrDays(c.start||e.entry,hrToday())*100/Math.max(1,hrDays(c.start||e.entry,c.end))))}%"></i><span>${hrE(hrDate(c.end))}</span></div>`:""}
   <dl class="hr-dl two"><div><dt>${hrE(L4("Début|Start|Beginn|البداية"))}</dt><dd>${hrE(hrDate(c.start||e.entry))}</dd></div><div><dt>${hrE(L4("Fin|End|Ende|النهاية"))}</dt><dd>${c.end?hrE(hrDate(c.end)):hrE(L4("Indéterminée|Open-ended|Unbefristet|غير محددة"))}</dd></div><div><dt>${hrE(L4("Fin de période d’essai|Probation ends|Probezeit bis|نهاية التجربة"))}</dt><dd>${c.trialEnd?hrE(hrDate(c.trialEnd)):"—"}</dd></div><div><dt>${hrE(L4("Temps de travail|Working time|Arbeitszeit|وقت العمل"))}</dt><dd>${hrE(hrWT(e))} · ${hrNf(e.hours)} h</dd></div><div class="w"><dt>${hrE(L4("Convention collective|Collective agreement|Tarifvertrag|الاتفاقية الجماعية"))}</dt><dd>${hrE(c.cc||"—")}</dd></div></dl>
   ${hrCan("edit.contract")?`<button type="button" class="hr-btn sm" data-hramend="${e.id}">${hri("pen",14)}${hrE(L4("Enregistrer un avenant…|Record an amendment…|Nachtrag erfassen…|تسجيل ملحق…"))}</button>`:""}<p class="hr-mut sm">${hrE(L4("Aucune règle légale n’est appliquée automatiquement (durées maximales, renouvellements, indemnités) : à vérifier selon le droit applicable.|No legal rule is applied automatically (maximum durations, renewals, allowances): check against applicable law.|Keine automatischen Rechtsregeln.|لا تُطبق قواعد قانونية تلقائيًا."))}</p></section>
   <section class="hr-card"><h3>${hri("hist",16)}${hrE(L4("Historique contractuel|Contract history|Vertragshistorie|تاريخ العقد"))}</h3><ol class="hr-tl">${(c.hist||[]).map(h=>`<li><b>${hrE(L4(h.t))}</b><small>${hrE(hrDate(h.d))}</small></li>`).join("")}</ol><h4>${hrE(L4("Documents contractuels|Contract documents|Vertragsdokumente|مستندات العقد"))}</h4><ul class="hr-mini">${cd.map(x=>`<li>${hri("file",14)}<span class="nm">${hrE(x.name)}</span><small>${hrE(hrDate(x.d))}</small></li>`).join("")||`<li class="hr-mut">—</li>`}</ul></section></div>`}
function hrDocsHTML(e: HrEmp){return `<section class="hr-card"><div class="hr-ch"><h3>${hri("folder",16)}${hrE(L4("Documents RH|HR documents|HR-Dokumente|مستندات الموارد البشرية"))}</h3>${hrCan("docs.add")?`<label class="hr-btn sm pri">${hri("ul",14)}${hrE(L4("Ajouter un document…|Add a document…|Dokument hinzufügen…|إضافة مستند…"))}<input type="file" data-hrdocup="${e.id}" hidden></label>`:""}</div>
  ${(e.docs||[]).length?`<table class="hr-tb sm"><thead><tr><th>${hrE(L4("Document|Document|Dokument|المستند"))}</th><th>${hrE(L4("Type|Type|Art|النوع"))}</th><th>${hrE(L4("Date|Date|Datum|التاريخ"))}</th><th class="num">${hrE(L4("Taille|Size|Größe|الحجم"))}</th><th></th></tr></thead><tbody>${e.docs.slice().sort((a,b)=>a.d<b.d?1:-1).map(x=>`<tr><td>${hri("file",14)} ${hrE(x.name)}</td><td>${hrE(L4(HR_DOCTYPES[x.type]||x.type))}</td><td>${hrE(hrDate(x.d))}</td><td class="num">${hrNf(Math.ceil(x.size/1024))} Ko</td><td class="act">${x.file?`<button type="button" class="hr-btn sm" data-hrdocdl="${e.id}|${x.id}">${hri("dl",13)}${hrE(L4("Ouvrir|Open|Öffnen|فتح"))}</button>`:`<span class="hr-mut sm" title="${hrE(L4("Document de démonstration : seules les métadonnées existent.|Demo document: only metadata exists.|Nur Metadaten.|بيانات وصفية فقط."))}">${hrE(L4("métadonnées seules|metadata only|nur Metadaten|بيانات وصفية فقط"))}</span>`}${hrCan("docs.add")&&x.file?`<button type="button" class="hr-ib sm" data-hrdocdel="${e.id}|${x.id}" aria-label="${hrE(L4("Supprimer|Delete|Löschen|حذف"))}">${hri("trash",13)}</button>`:""}</td></tr>`).join("")}</tbody></table>`:hrEmpty("folder",L4("Aucun document.|No documents.|Keine Dokumente.|لا مستندات."))}<p class="hr-mut sm">${hrE(L4("Fichiers de 400 Ko maximum, conservés dans ce navigateur.|Files up to 400 KB, kept in this browser.|Dateien bis 400 KB, im Browser.|ملفات حتى 400 ك.ب."))}</p></section>`}

