function hrDeactDlg(ids: string[]){const es=(ids.map(hrEmp) as HrEmp[]).filter(e=>e&&e.status!=="left");if(!es.length){hrToast(L4("Aucun employé actif dans la sélection.|No active employee in the selection.|Keine aktiven in der Auswahl.|لا موظفين نشطين."));return}
  hrDialog(L4("Enregistrer une sortie|Record a departure|Austritt erfassen|تسجيل مغادرة"),`<p class="hr-cmsg">${hrE(L4("Le dossier est conservé et passe au statut « Sorti ». Aucun compte utilisateur n’est modifié par cette action.|The record is kept and set to “Left”. No user account is changed by this action.|Die Akte bleibt erhalten (Status „Ausgeschieden“).|يُحفظ الملف بحالة «غادر»."))}</p><ul class="hr-who-list">${es.map(e=>`<li>${hrAvatar(e,24)}${hrE(hrName(e))} <small>${hrE(e.job)}</small></li>`).join("")}</ul><div class="hr-flds"><div class="hr-fld"><label>${hrE(L4("Date de sortie|Leaving date|Austrittsdatum|تاريخ المغادرة"))}</label><input type="date" class="hr-in" data-dd value="${hrToday()}"></div><div class="hr-fld full"><label>${hrE(L4("Motif (interne)|Reason (internal)|Grund (intern)|السبب"))} <em>*</em></label><input class="hr-in" data-dw autofocus></div></div>`,
  {danger:true,okLabel:L4("Confirmer la sortie|Confirm departure|Austritt bestätigen|تأكيد المغادرة"),icon:"userX",onOk:m=>{const w=m.querySelector<HTMLInputElement>("[data-dw]")!.value.trim();if(!w)throw new HrErr("hr_eInvalid",L4("motif requis|reason required|Grund fehlt|السبب مطلوب"));const d=m.querySelector<HTMLInputElement>("[data-dd]")!.value;if(!hrValidDate(d))throw new HrErr("hr_eInvalid",L4("date|date|Datum|التاريخ"));es.forEach(e=>hrDeactivate(e.id,d,w));HR.ui.sel=[];hrSave(true);hrToast(es.length+" "+L4("sortie(s) enregistrée(s)|departure(s) recorded|Austritt(e) erfasst|مغادرة مسجلة"));hrRefresh();return true}})}
function hrArchDlg(ids: string[]){const es=(ids.map(hrEmp) as HrEmp[]).filter(e=>e&&e.status==="left"&&!e.archived);if(!es.length){hrToast(L4(HR_ERR.hr_eArchiveActive));return}hrConfirm(L4("Archiver ces dossiers ? Ils disparaissent des listes mais restent consultables par un administrateur.|Archive these records? They leave the lists but remain available to administrators.|Akten archivieren?|أرشفة الملفات؟")+" ("+es.length+")",()=>{es.forEach(e=>hrArchive(e.id));HR.ui.sel=[];hrSave(true);hrToast(es.length+" "+L4("dossier(s) archivé(s)|record(s) archived|archiviert|مؤرشف"));hrRefresh()},{danger:true,okLabel:L4("Archiver|Archive|Archivieren|أرشفة")})}
