  if(k==="pro")return `<div class="hr-flds">${f("job",HR_FN.job,`<input id="hw-job" class="hr-in" data-hw="job" value="${v("job")}" list="hw-jobs" autofocus><datalist id="hw-jobs">${[...new Set(HR.st!.emps.map(e=>e.job))].map(j=>`<option value="${hrE(j)}">`).join("")}</datalist>`,{req:1,hint:"Ex. Kinésithérapeute, Comptable, Infirmier…|E.g. Physiotherapist, Accountant, Nurse…|z. B. Physiotherapeut…|مثال: أخصائي علاج طبيعي…"})}${f("status","Statut à l’arrivée|Status on arrival|Status bei Eintritt|الحالة عند الالتحاق",`<select id="hw-status" class="hr-in" data-hw="status">${hrOpts([["trial",L4(HR_STATUS.trial)],["active",L4(HR_STATUS.active)]],w.status)}</select>`)}</div>`;
